      "proposed_laureates": [
        "Christian J. Bordé",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Matter-wave interferometry has made atoms into highly precise probes of gravity, motion, and fundamental constants, opening a major experimental field.",
        "attribution": "Bordé established essential light-pulse atom-interferometry ideas, while Kasevich drove landmark precision demonstrations and applications.",
        "maturity": "The methods are well established across laboratories and have delivered mature gravimeters, gyroscopes, and precision tests.",
        "uncertainties": [
          "David E. Pritchard's relative claim to the central discovery versus later field-building should be scrutinized."
        ]
      }
    },
